// Shared vocabulary for complaints / escalations, used by the consumer,
// farmer and moderator APIs so the categories never drift apart.

export const COMPLAINT_TYPES = [
  'delivery_delay',
  'quality_complaint',
  'payment_issue',
  'other',
] as const

export type ComplaintType = (typeof COMPLAINT_TYPES)[number]

export function normalizeComplaintType(raw: unknown): ComplaintType {
  const v = String(raw ?? 'other')
  return (COMPLAINT_TYPES as readonly string[]).includes(v) ? (v as ComplaintType) : 'other'
}

export const COMPLAINT_TYPE_LABEL: Record<ComplaintType, string> = {
  delivery_delay: 'Delivery delay',
  quality_complaint: 'Quality complaint',
  payment_issue: 'Payment issue',
  other: 'Other',
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { getModeratorZone } from '@/lib/moderator-session'
import { normalizeComplaintType } from '@/lib/complaints'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

// GET — the signed-in consumer's own complaints, newest first, each with the
// linked order's human code when there is one.
export async function GET(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })
  const supabase = svc()

  const { data: rows, error } = await supabase
    .from('escalations')
    .select('id, order_id, type, description, status, resolution_notes, resolved_at, created_at')
    .eq('raised_by_role', 'consumer')
    .eq('raised_by_id', session.consumerId)
    .order('created_at', { ascending: false })
  if (error) {
    console.error('[YFF consumer/complaints] query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  const orderIds = (rows ?? []).map((r) => r.order_id).filter(Boolean) as string[]
  const codeById = new Map<string, string>()
  if (orderIds.length > 0) {
    const { data: orders } = await supabase.from('orders').select('id, order_code').in('id', orderIds)
    for (const o of orders ?? []) codeById.set(o.id, o.order_code ?? '')
  }
  const complaints = (rows ?? []).map((r) => ({
    ...r,
    order_code: r.order_id ? codeById.get(r.order_id) ?? null : null,
  }))
  return NextResponse.json({ complaints })
}

// POST — a consumer files a complaint. "Raised by" is taken from their account
// (never trusted from the client). An optional order_code is accepted and must
// belong to this consumer; it pins the complaint to the right zone's moderator.
//   { type, description, order_code? }
export async function POST(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })
  const supabase = svc()

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })
  const b = body as Record<string, unknown>

  const type = normalizeComplaintType(b.type)
  const description = String(b.description ?? '').trim()
  const orderCode = String(b.order_code ?? '').trim()
  if (!description) return NextResponse.json({ error: 'Please describe the problem.' }, { status: 400 })
  if (description.length > 2000) return NextResponse.json({ error: 'Description is too long.' }, { status: 400 })

  // Identity comes from the account, not the request.
  const { data: me } = await supabase
    .from('consumers_auth').select('name, phone').eq('id', session.consumerId).maybeSingle()
  const raisedByName = (me?.name || 'Consumer').trim()
  const raisedByPhone = me?.phone ?? null

  // Resolve the zone. Default to the launch zone; if tied to an order, use that
  // order's farmer's zone so the complaint lands with the right moderator.
  let region_slug = getModeratorZone()
  let order_id: string | null = null
  if (orderCode) {
    const { data: order } = await supabase
      .from('orders')
      .select('id, consumer_id, farmer_id')
      .eq('order_code', orderCode)
      .maybeSingle()
    if (!order) return NextResponse.json({ error: `No order found with code ${orderCode}.` }, { status: 400 })
    if (order.consumer_id !== session.consumerId) {
      return NextResponse.json({ error: 'That order is not on your account.' }, { status: 403 })
    }
    order_id = order.id
    if (order.farmer_id) {
      const { data: farmer } = await supabase
        .from('farmers').select('region_slug').eq('id', order.farmer_id).maybeSingle()
      if (farmer?.region_slug) region_slug = farmer.region_slug
    }
  }

  const { data: inserted, error } = await supabase
    .from('escalations')
    .insert({
      region_slug,
      type,
      description,
      order_id,
      status: 'open',
      raised_by: raisedByName,
      raised_by_role: 'consumer',
      raised_by_id: session.consumerId,
      raised_by_phone: raisedByPhone,
    })
    .select('id')
    .single()
  if (error) {
    console.error('[YFF consumer/complaints] insert failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
  return NextResponse.json({ id: inserted.id })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'
import { getModeratorZone } from '@/lib/moderator-session'
import { normalizeComplaintType } from '@/lib/complaints'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

// GET — the signed-in farmer's own complaints, newest first.
export async function GET(req: NextRequest) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })
  const supabase = svc()

  const { data: rows, error } = await supabase
    .from('escalations')
    .select('id, order_id, type, description, status, resolution_notes, resolved_at, created_at')
    .eq('raised_by_role', 'farmer')
    .eq('raised_by_id', session.farmerId)
    .order('created_at', { ascending: false })
  if (error) {
    console.error('[YFF farmer/complaints] query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  const orderIds = (rows ?? []).map((r) => r.order_id).filter(Boolean) as string[]
  const codeById = new Map<string, string>()
  if (orderIds.length > 0) {
    const { data: orders } = await supabase.from('orders').select('id, order_code').in('id', orderIds)
    for (const o of orders ?? []) codeById.set(o.id, o.order_code ?? '')
  }
  const complaints = (rows ?? []).map((r) => ({
    ...r,
    order_code: r.order_id ? codeById.get(r.order_id) ?? null : null,
  }))
  return NextResponse.json({ complaints })
}

// POST — a farmer files a complaint. Identity + zone come from their farmer
// record. An optional order_code is accepted and must be one of their orders.
//   { type, description, order_code? }
export async function POST(req: NextRequest) {
  const session = getFarmerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })
  const supabase = svc()

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })
  const b = body as Record<string, unknown>

  const type = normalizeComplaintType(b.type)
  const description = String(b.description ?? '').trim()
  const orderCode = String(b.order_code ?? '').trim()
  if (!description) return NextResponse.json({ error: 'Please describe the problem.' }, { status: 400 })
  if (description.length > 2000) return NextResponse.json({ error: 'Description is too long.' }, { status: 400 })

  const { data: me } = await supabase
    .from('farmers').select('name, phone, region_slug').eq('id', session.farmerId).maybeSingle()
  if (!me) return NextResponse.json({ error: 'Farmer account not found.' }, { status: 404 })
  const region_slug = me.region_slug || getModeratorZone()

  let order_id: string | null = null
  if (orderCode) {
    const { data: order } = await supabase
      .from('orders')
      .select('id, farmer_id')
      .eq('order_code', orderCode)
      .maybeSingle()
    if (!order) return NextResponse.json({ error: `No order found with code ${orderCode}.` }, { status: 400 })
    if (order.farmer_id !== session.farmerId) {
      return NextResponse.json({ error: 'That order is not one of yours.' }, { status: 403 })
    }
    order_id = order.id
  }

  const { data: inserted, error } = await supabase
    .from('escalations')
    .insert({
      region_slug,
      type,
      description,
      order_id,
      status: 'open',
      raised_by: (me.name || 'Farmer').trim(),
      raised_by_role: 'farmer',
      raised_by_id: session.farmerId,
      raised_by_phone: me.phone ?? null,
    })
    .select('id')
    .single()
  if (error) {
    console.error('[YFF farmer/complaints] insert failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
  return NextResponse.json({ id: inserted.id })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

const TYPES = ['delivery_delay', 'quality_complaint', 'payment_issue', 'other'] as const

// GET — every escalation in the moderator's zone, newest first, with the linked
// order's human code (e.g. "Order #YFF-1042") when there is one.
export async function GET(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone()
  const supabase = svc()

  const { data: rows, error } = await supabase
    .from('escalations')
    .select('id, order_id, type, description, raised_by, raised_by_role, raised_by_phone, status, resolution_notes, resolved_at, created_at')
    .eq('region_slug', zone)
    .order('created_at', { ascending: false })
  if (error) {
    console.error('[YFF moderator/escalations] query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  // Attach order codes for any escalations that reference an order.
  const orderIds = (rows ?? []).map((r) => r.order_id).filter(Boolean) as string[]
  const codeById = new Map<string, string>()
  if (orderIds.length > 0) {
    const { data: orders } = await supabase.from('orders').select('id, order_code').in('id', orderIds)
    for (const o of orders ?? []) codeById.set(o.id, o.order_code ?? '')
  }
  const escalations = (rows ?? []).map((r) => ({ ...r, order_code: r.order_id ? codeById.get(r.order_id) ?? null : null }))
  return NextResponse.json({ escalations })
}

// POST — log a complaint that came in by phone/WhatsApp. Optionally tie it to an
// order via its order_code (must be an order from a farmer in this zone).
export async function POST(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone()
  const supabase = svc()

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })
  const b = body as Record<string, unknown>

  const typeRaw = String(b.type ?? 'other')
  const type = (TYPES as readonly string[]).includes(typeRaw) ? typeRaw : 'other'
  const description = String(b.description ?? '').trim()
  let raised_by = String(b.raised_by ?? '').trim() || null
  let raised_by_phone: string | null = null
  const orderCode = String(b.order_code ?? '').trim()
  if (!description) return NextResponse.json({ error: 'Describe the complaint.' }, { status: 400 })

  // Resolve an optional order_code to an order in this zone. When one is given,
  // the buyer's name and phone come straight off the order so "raised by" is
  // auto-filled and the moderator always has a number to call back on.
  let order_id: string | null = null
  if (orderCode) {
    const { data: order } = await supabase
      .from('orders')
      .select('id, farmer_id, buyer_name, buyer_phone')
      .eq('order_code', orderCode)
      .maybeSingle()
    if (order?.farmer_id) {
      const { data: farmer } = await supabase
        .from('farmers').select('region_slug').eq('id', order.farmer_id).maybeSingle()
      if (farmer?.region_slug !== zone) {
        return NextResponse.json({ error: 'That order is not in your zone.' }, { status: 400 })
      }
      order_id = order.id
      raised_by_phone = order.buyer_phone ?? null
      if (!raised_by) raised_by = order.buyer_name?.trim() || null
    } else {
      return NextResponse.json({ error: `No order found with code ${orderCode}.` }, { status: 400 })
    }
  }

  const { data: inserted, error } = await supabase
    .from('escalations')
    .insert({ region_slug: zone, type, description, raised_by, raised_by_role: 'moderator', raised_by_phone, order_id, status: 'open' })
    .select('id')
    .single()
  if (error) {
    console.error('[YFF moderator/escalations] insert failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
  return NextResponse.json({ id: inserted.id })
}

'use client'

import { useCallback, useEffect, useState } from 'react'
import ModeratorShell, { useModeratorAuth } from '../ModeratorShell'

type Escalation = {
  id: string
  order_id: string | null
  order_code: string | null
  type: string
  description: string
  raised_by: string | null
  raised_by_role: 'consumer' | 'farmer' | 'moderator' | null
  raised_by_phone: string | null
  status: 'open' | 'in_progress' | 'resolved'
  resolution_notes: string | null
  resolved_at: string | null
  created_at: string
}

const TYPE_LABEL: Record<string, string> = {
  delivery_delay: 'Delivery delay',
  quality_complaint: 'Quality complaint',
  payment_issue: 'Payment issue',
  other: 'Other',
}

const ROLE_LABEL: Record<string, string> = {
  consumer: 'Consumer',
  farmer: 'Farmer',
  moderator: 'Logged by team',
}

const STATUS_STYLE: Record<string, string> = {
  open: 'bg-red-100 text-red-600',
  in_progress: 'bg-amber-100 text-amber-700',
  resolved: 'bg-green-100 text-green-700',
}

function timeAgo(iso: string): string {
  const mins = Math.floor((Date.now() - new Date(iso).getTime()) / 60000)
  if (mins < 60) return `${mins}m ago`
  const hrs = Math.floor(mins / 60)
  if (hrs < 24) return `${hrs}h ago`
  return `${Math.floor(hrs / 24)}d ago`
}

export default function ModeratorEscalationsPage() {
  const { zone, checked } = useModeratorAuth()
  const [items, setItems] = useState<Escalation[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [busyId, setBusyId] = useState<string | null>(null)
  const [resolving, setResolving] = useState<Escalation | null>(null)
  const [notes, setNotes] = useState('')
  const [showNew, setShowNew] = useState(false)

  const load = useCallback(async () => {
    setLoading(true)
    const r = await fetch('/api/moderator/escalations', { credentials: 'same-origin' }).catch(() => null)
    setLoading(false)
    if (!r) { setError('Network error.'); return }
    const json = await r.json().catch(() => ({}))
    if (!r.ok) { setError(json?.error ?? 'Could not load escalations.'); return }
    setItems((json.escalations ?? []) as Escalation[])
  }, [])

  useEffect(() => { if (checked) void load() }, [checked, load])

  const setStatus = async (e: Escalation, status: Escalation['status'], resolution_notes?: string) => {
    if (busyId) return
    setBusyId(e.id)
    const r = await fetch(`/api/moderator/escalations/${e.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ status, resolution_notes }),
    }).catch(() => null)
    setBusyId(null)
    if (!r || !r.ok) {
      const json = r ? await r.json().catch(() => ({})) : {}
      setError(json?.error ?? 'Update failed.'); return
    }
    setResolving(null); setNotes('')
    void load()
  }

  if (!checked || !zone) {
    return (
      <main className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="w-10 h-10 border-4 border-green-700 border-t-transparent rounded-full animate-spin" />
      </main>
    )
  }

  const open = items.filter((i) => i.status !== 'resolved')
  const resolved = items.filter((i) => i.status === 'resolved')

  return (
    <ModeratorShell title="Escalations" subtitle="Complaints and disputes in your zone" zone={zone}>
      <div className="flex items-center justify-between mb-4">
        <p className="text-[11px] font-bold text-gray-400 uppercase tracking-wide">
          {open.length} open · {resolved.length} resolved
        </p>
        <button
          onClick={() => setShowNew(true)}
          className="bg-green-800 text-white text-sm font-bold px-4 py-2 rounded-xl active:bg-green-900"
        >
          + Log a complaint
        </button>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 text-red-700 rounded-xl px-4 py-2 text-sm font-semibold mb-4">{error}</div>
      )}

      {loading ? (
        <p className="text-sm text-gray-400 py-10 text-center">Loading…</p>
      ) : items.length === 0 ? (
        <div className="text-center py-14 bg-white rounded-2xl border border-gray-100">
          <div className="text-5xl mb-3">✅</div>
          <p className="font-semibold text-gray-500 text-sm">No escalations — all clear</p>
        </div>
      ) : (
        <div className="space-y-3">
          {[...open, ...resolved].map((e) => (
            <div key={e.id} className="bg-white rounded-2xl border border-gray-100 p-4 shadow-sm">
              <div className="flex items-start justify-between gap-3">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full ${STATUS_STYLE[e.status]}`}>
                    {e.status === 'in_progress' ? 'In progress' : e.status === 'open' ? 'Open' : 'Resolved'}
                  </span>
                  <span className="text-[10px] font-semibold px-2 py-0.5 rounded-full bg-gray-100 text-gray-600">
                    {TYPE_LABEL[e.type] ?? e.type}
                  </span>
                </div>
                <span className="text-[11px] text-gray-400 whitespace-nowrap">{timeAgo(e.created_at)}</span>
              </div>

              <p className="font-bold text-gray-900 text-sm mt-2">
                {e.order_code ? `Order #${e.order_code} — ` : ''}{e.description}
              </p>
              {e.raised_by && (
                <p className="text-xs text-gray-500 mt-0.5">
                  Raised by {e.raised_by}
                  {e.raised_by_role && <span className="text-gray-400"> ({ROLE_LABEL[e.raised_by_role] ?? e.raised_by_role})</span>}
                </p>
              )}

              {/* Callback contact — copied from the raiser's profile */}
              {e.raised_by_phone && (
                <div className="flex items-center gap-2 mt-2">
                  <a
                    href={`tel:+91${e.raised_by_phone}`}
                    className="inline-flex items-center gap-1 text-xs font-bold text-green-700 border border-green-200 rounded-lg px-2.5 py-1 active:bg-green-50"
                  >
                    📞 +91 {e.raised_by_phone}
                  </a>
                  <a
                    href={`https://wa.me/91${e.raised_by_phone.replace(/\D/g, '')}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-xs font-bold text-green-700 border border-green-200 rounded-lg px-2.5 py-1 active:bg-green-50"
                  >
                    💬 WhatsApp
                  </a>
                </div>
              )}

              {e.status === 'resolved' && e.resolution_notes && (
                <p className="mt-2 text-xs text-green-700 bg-green-50 rounded-lg px-3 py-2">
                  Resolved: {e.resolution_notes}
                </p>
              )}

              {e.status !== 'resolved' && (
                <div className="flex flex-wrap gap-2 mt-3">
                  {e.status === 'open' && (
                    <button
                      onClick={() => setStatus(e, 'in_progress')}
                      disabled={busyId === e.id}
                      className="bg-white border border-amber-200 text-amber-700 text-xs font-bold px-3 py-1.5 rounded-lg active:bg-amber-50 disabled:opacity-50"
                    >
                      Mark in progress
                    </button>
                  )}
                  <button
                    onClick={() => { setResolving(e); setNotes('') }}
                    disabled={busyId === e.id}
                    className="bg-green-700 text-white text-xs font-bold px-3 py-1.5 rounded-lg active:bg-green-800 disabled:opacity-50"
                  >
                    Mark resolved
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {resolving && (
        <ModalShell title={`Resolve: ${resolving.description.slice(0, 40)}`} onClose={() => setResolving(null)}>
          <p className="text-xs text-gray-500 mb-2">Note what was done. This is kept on the record.</p>
          <textarea
            value={notes} onChange={(ev) => setNotes(ev.target.value)} rows={3} autoFocus
            placeholder="e.g. Called farmer, re-delivered next morning, consumer satisfied"
            className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm focus:outline-none focus:border-green-500"
          />
          <div className="flex gap-2 mt-3 justify-end">
            <button onClick={() => setResolving(null)} className="text-sm text-gray-500 px-3 py-2">Cancel</button>
            <button
              onClick={() => setStatus(resolving, 'resolved', notes.trim())}
              disabled={!notes.trim() || busyId === resolving.id}
              className="bg-green-700 text-white text-sm font-bold px-4 py-2 rounded-xl disabled:opacity-50"
            >
              Mark resolved
            </button>
          </div>
        </ModalShell>
      )}

      {showNew && <NewComplaintModal onClose={() => setShowNew(false)} onCreated={() => { setShowNew(false); void load() }} />}
    </ModeratorShell>
  )
}

function ModalShell({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) {
  return (
    <div className="fixed inset-0 z-40 bg-black/40 flex items-end md:items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-md p-5" onClick={(e) => e.stopPropagation()}>
        <p className="font-bold text-gray-900 mb-1">{title}</p>
        {children}
      </div>
    </div>
  )
}

const TYPE_OPTIONS = [
  { value: 'delivery_delay', label: 'Delivery delay' },
  { value: 'quality_complaint', label: 'Quality complaint' },
  { value: 'payment_issue', label: 'Payment issue' },
  { value: 'other', label: 'Other' },
]

function NewComplaintModal({ onClose, onCreated }: { onClose: () => void; onCreated: () => void }) {
  const [type, setType] = useState('quality_complaint')
  const [description, setDescription] = useState('')
  const [raisedBy, setRaisedBy] = useState('')
  const [raisedByEdited, setRaisedByEdited] = useState(false)
  const [orderCode, setOrderCode] = useState('')
  const [lookupPhone, setLookupPhone] = useState<string | null>(null)
  const [looking, setLooking] = useState(false)
  const [saving, setSaving] = useState(false)
  const [err, setErr] = useState('')

  // When an order code is entered, pull the buyer's name + phone off the order so
  // "Raised by" is auto-filled and we have a number to call back on. We don't
  // overwrite a name the moderator typed themselves.
  const lookupOrder = async (code: string) => {
    const c = code.trim()
    setLookupPhone(null)
    if (!c) return
    setLooking(true)
    const r = await fetch(`/api/moderator/orders/lookup?code=${encodeURIComponent(c)}`, { credentials: 'same-origin' }).catch(() => null)
    setLooking(false)
    if (!r || !r.ok) return
    const j = await r.json().catch(() => ({}))
    setLookupPhone(j?.buyer_phone ?? null)
    if (!raisedByEdited && j?.buyer_name) setRaisedBy(j.buyer_name)
  }

  const submit = async () => {
    if (!description.trim()) { setErr('Describe the complaint.'); return }
    setSaving(true); setErr('')
    const r = await fetch('/api/moderator/escalations', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ type, description: description.trim(), raised_by: raisedBy.trim(), order_code: orderCode.trim() }),
    }).catch(() => null)
    setSaving(false)
    if (!r || !r.ok) { const j = r ? await r.json().catch(() => ({})) : {}; setErr(j?.error ?? 'Could not save.'); return }
    onCreated()
  }

  return (
    <ModalShell title="Log a complaint" onClose={onClose}>
      {err && <p className="text-xs text-red-600 mb-2">{err}</p>}
      <label className="block text-xs font-semibold text-gray-500 mb-1">Type</label>
      <select value={type} onChange={(e) => setType(e.target.value)} className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm mb-3">
        {TYPE_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
      <label className="block text-xs font-semibold text-gray-500 mb-1">What happened?</label>
      <textarea
        value={description} onChange={(e) => setDescription(e.target.value)} rows={3} autoFocus
        placeholder="e.g. Paid ₹360 for tomatoes at 10 AM, nothing arrived by 6 PM"
        className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm mb-3 focus:outline-none focus:border-green-500"
      />
      <div className="grid grid-cols-2 gap-2 mb-1">
        <div>
          <label className="block text-xs font-semibold text-gray-500 mb-1">Order code <span className="text-gray-300">(optional)</span></label>
          <input
            value={orderCode}
            onChange={(e) => setOrderCode(e.target.value)}
            onBlur={(e) => void lookupOrder(e.target.value)}
            placeholder="YFF-1042"
            className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm"
          />
        </div>
        <div>
          <label className="block text-xs font-semibold text-gray-500 mb-1">Raised by</label>
          <input
            value={raisedBy}
            onChange={(e) => { setRaisedBy(e.target.value); setRaisedByEdited(true) }}
            placeholder="Ravi Sharma"
            className="w-full border border-gray-200 rounded-xl px-3 py-2 text-sm"
          />
        </div>
      </div>
      <p className="text-[11px] text-gray-400 mb-3 h-4">
        {looking ? 'Looking up order…' : lookupPhone ? `📞 +91 ${lookupPhone} — auto-filled from the order` : 'Enter an order code to auto-fill the buyer’s name and phone.'}
      </p>
      <div className="flex gap-2 justify-end">
        <button onClick={onClose} className="text-sm text-gray-500 px-3 py-2">Cancel</button>
        <button onClick={submit} disabled={saving} className="bg-green-800 text-white text-sm font-bold px-4 py-2 rounded-xl disabled:opacity-50">
          {saving ? 'Saving…' : 'Save complaint'}
        </button>
      </div>
    </ModalShell>
  )
}

