                  </span>
                </div>
                {c.order_code && <p className="text-[11px] font-mono font-semibold text-gray-400 mt-1.5">Order {c.order_code}</p>}
                <p className="text-sm text-gray-900 mt-1 leading-snug">{c.description}</p>
